package blockbranch.realistic;
import java.util.*;
public final class GroveCheck {
 public static void main(String[]args){GroveSiteCheck.verify();taper();var shapes=new HashSet<String>();for(int i=0;i<64;i++){var r=new WoodlandTrees.Root(0,0,0,false,16,(int)OakBirchWoodland.mix(i*1297L),6);var tree=BorealTrees.tree(r);var map=new HashMap<String,Integer>();var shape=new TreeSet<String>();for(var v:tree){map.put(v.x()+","+v.y()+","+v.z(),v.code());shape.add(v.x()+","+v.y()+","+v.z());}shapes.add(shape.toString());for(var v:tree)if(v.code()>=22&&v.code()<=27){int distance=WoodlandTrees.leafDistance(v.code());boolean supported=false;for(var q:TaigaCheck.DIR){int n=map.getOrDefault((v.x()+q[0])+","+(v.y()+q[1])+","+(v.z()+q[2]),0);if(WoodlandTrees.logCode(n)&&distance==1||n>=22&&n<=27&&WoodlandTrees.leafDistance(n)<distance)supported=true;}require(supported,"Grove leaves have connected native-distance support");}}require(shapes.size()>55,"Grove shape variation at fixed age/height");
 for(long seed:new long[]{424242,1,-17}){var d=new DrainageNetwork(new TerrainShape(seed),seed);var c=new ClimateField(seed);var e=new GroundEcology.Field(d::sample,c);int selected=0,fromSnow=0,fromMixed=0,snowBefore=0,mixedBefore=0,taiga=0;for(int z=-1900000;z<=1900000;z+=16000)for(int x=-1900000;x<=1900000;x+=16000){boolean snow=SnowyTaiga.contains(seed,x,z,d,c),mixed=BorealWoodland.contains(seed,x,z,d,c)&&!snow&&!Taiga.contains(seed,x,z,d,c);if(snow)snowBefore++;if(mixed)mixedBefore++;if(Taiga.contains(seed,x,z,d,c))taiga++;boolean grove=Grove.contains(seed,x,z,d,c,e);require(grove==Grove.contains(seed,x,z,d,c),"Cached/uncached ecological sampling agrees");if(!grove)continue;selected++;if(snow)fromSnow++;else if(mixed)fromMixed++;else throw new AssertionError("Unexpected previous domain");require(!AlpineScree.contains(x,z,d::sample)&&!SnowySlopes.contains(x,z,d,c)&&!MontaneMeadow.contains(seed,x,z,d,c)&&!Taiga.contains(seed,x,z,d,c),"Preserve exposed scree,open snow,Meadow and ordinary Taiga");}require(selected>=20&&snowBefore-fromSnow>=snowBefore*.7&&mixedBefore-fromMixed>=mixedBefore*.9,"Meaningful Grove and substantial retained cold woodland");var p=blockbranch.realistic.GroveFixtures.fixture(d,seed);var roots=BorealTrees.roots(seed,p.x()-48,p.z()-48,p.x()+48,p.z()+48,d,c);require(roots.stream().filter(r->r.family()==6).count()>=8,"Actual characteristic grouped Grove trees");var arrays=new LinkedHashMap<String,int[]>();int snow=0,wood=0;var layerCodes=new HashSet<Integer>();for(int cz=(p.z()>>4)-2;cz<=(p.z()>>4)+2;cz++)for(int cx=(p.x()>>4)-2;cx<=(p.x()>>4)+2;cx++){var raw=WoodlandTrees.column(seed,cx,cz,d,c);var a=Grove.snowColumn(seed,cx,cz,raw,d,c,e);require(a.length<12288,"Bounded Grove tree/snow overlay");arrays.put(cx+","+cz,a);for(int v:a){int k=v>>>blockbranch.cubic.CanopyLayer.STATE_BITS,code=v&blockbranch.cubic.CanopyLayer.STATE_MASK,wx=cx*16+(k&15),wz=cz*16+((k>>>4)&15),y=(k>>>8)+TerrainShape.FLOOR;if(code>=78&&code<=80)wood++;if(SnowyTaiga.snow(code)){snow++;layerCodes.add(code);require(y>d.sample(wx,wz).height()&&d.sample(wx,wz).waterLevel()==DrainageNetwork.DRY,"Dry supported snow/canopy hydrology");}}}System.out.println("GROVE_OVERLAY_DIAGNOSTIC seed="+seed+" point="+p+" snow="+snow+" wood="+wood+" layers="+layerCodes);require(snow>100&&wood>100&&layerCodes.size()>=2,"Snowy Grove structure and varied retention");var keys=new ArrayList<>(arrays.keySet());Collections.reverse(keys);for(var k:keys){var q=k.split(",");int x=Integer.parseInt(q[0]),z=Integer.parseInt(q[1]);require(Arrays.equals(arrays.get(k),Grove.snowColumn(seed,x,z,WoodlandTrees.column(seed,x,z,d,c),d,c,e)),"Grove request-order/negative-coordinate canopy seams");}System.out.println("GROVE seed="+seed+" selected="+selected+" retainedSnowyTaiga="+(snowBefore-fromSnow)+" originalSnowy="+snowBefore+" retainedMixedBoreal="+(mixedBefore-fromMixed)+" originalMixed="+mixedBefore+" ordinaryTaiga="+taiga+" point="+p+" roots="+roots.stream().filter(r->r.family()==6).count()+" snow="+snow+" wood="+wood+" layers="+layerCodes);}
 System.out.println("GROVE_MONTANE_PARTITION_COHORTS_SUPPORT_SNOW_ORDER_PASS");}
 static void taper(){
  // Original offending 13m Grove tree: max layer area was only 9, with a long
  // five-cell cross section. This fixed profile rejects that pillar independently
  // of camera or stand selection; broad lower boughs must narrow into a leader.
  for(int h:new int[]{8,11,13,16,19}){var r=new WoodlandTrees.Root(0,0,0,false,h,-1027127155,6);int[] area=new int[h+2];for(var v:BorealTrees.tree(r))if(v.y()>=0&&v.y()<area.length)area[v.y()]++;int max=Arrays.stream(area).max().orElseThrow();require(max>=(h<11?12:16)&&area[h-2]<max*.45,"Fixed Grove conifer has modest lower reach and clear upper taper");System.out.println("GROVE_TAPER height="+h+" layers="+Arrays.toString(area));}
 }
 static void require(boolean b,String m){if(!b)throw new AssertionError(m);}
}
